export default {
  async fetch(request, env) {
    if (request.method !== 'POST') return new Response('POST {"prompt": "..."}', { status: 405 });
    const { prompt } = await request.json();
    if (!prompt || prompt.length > 4000) return new Response('prompt required (max 4000 chars)', { status: 400 });
    const out = await env.AI.run('@cf/meta/llama-3.1-8b-instruct', { messages: [{ role: 'user', content: prompt }] });
    return Response.json(out);
  },
};

files.nginx.conf:
server {
    listen 80;
    server_name example.com;
    return 301 https://$host$request_uri;
}
server {
    listen 443 ssl http2;
    server_name example.com;
    ssl_certificate /etc/letsencrypt/live/example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/example.com/privkey.pem;
    root /var/www/site;
    add_header X-Content-Type-Options nosniff;
    add_header Referrer-Policy strict-origin-when-cross-origin;
    add_header Content-Security-Policy "default-src 'self'";
    location ~* \.(css|js|png|jpg|svg|woff2)$ { expires 30d; }
    location / { try_files $uri $uri/ /index.html; }
}
